-- The rules of the request tables (F-03 contract section 2.3, SDS section 3.3). add_requests created the tables;
-- this migration adds what Prisma cannot express. It only adds objects and a column default, so the previous
-- revision's code keeps working against it.

-- The request number: REQ- plus six digits from a sequence, generated by the database, never by the client (BR-07).
CREATE SEQUENCE "request_number_seq" START WITH 1;

ALTER TABLE "request" ALTER COLUMN "request_number" SET DEFAULT ('REQ-'::text || lpad((nextval('request_number_seq'::regclass))::text, 6, '0'::text));

-- The amount is positive and at most 1,000,000.00 THB (BR-04). A CHECK passes on NULL, so amount is also NOT NULL.
ALTER TABLE "request" ADD CONSTRAINT "request_amount_range" CHECK (amount > 0 AND amount <= 1000000.00);

-- Nobody is the reviewer of their own request (BR-06).
ALTER TABLE "request" ADD CONSTRAINT "request_reviewer_not_requester" CHECK (requester_id <> assigned_reviewer_id);

-- A submitted request has no decider, date, or reason; a decided one has both a decider and a date (BR-11).
ALTER TABLE "request" ADD CONSTRAINT "request_decision_fields" CHECK (
  (status = 'SUBMITTED' AND decided_at IS NULL AND decided_by_id IS NULL AND decision_reason IS NULL)
  OR (status <> 'SUBMITTED' AND decided_at IS NOT NULL AND decided_by_id IS NOT NULL)
);

-- A rejection always has a reason that is not empty or blank (BR-12).
ALTER TABLE "request" ADD CONSTRAINT "request_rejection_reason" CHECK (
  status <> 'REJECTED' OR (decision_reason IS NOT NULL AND length(btrim(decision_reason)) > 0)
);

-- History is append-only (BR-13): no UPDATE or DELETE of a request_event row, even by a bug. Row triggers do not
-- fire on TRUNCATE; the application never truncates (a known gap, F-04 contract section 1.5).
CREATE FUNCTION request_event_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'request_event is append-only';
END;
$$;

CREATE TRIGGER request_event_append_only
  BEFORE UPDATE OR DELETE ON "request_event"
  FOR EACH ROW EXECUTE FUNCTION request_event_append_only();
